import{_ as t,H as l,f as i,i as a}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"16 | 云原生安全：不可忽视的关键因素","description":"","frontmatter":{},"headers":[{"level":2,"title":"云原生安全的特点","slug":"云原生安全的特点","link":"#云原生安全的特点","children":[]},{"level":2,"title":"云原生安全的 4 个 C","slug":"云原生安全的-4-个-c","link":"#云原生安全的-4-个-c","children":[]},{"level":2,"title":"Cloud","slug":"cloud","link":"#cloud","children":[]},{"level":2,"title":"Cluster","slug":"cluster","link":"#cluster","children":[{"level":3,"title":"控制平面安全","slug":"控制平面安全","link":"#控制平面安全","children":[]},{"level":3,"title":"数据平面安全","slug":"数据平面安全","link":"#数据平面安全","children":[]}]},{"level":2,"title":"容器 runtime 安全","slug":"容器-runtime-安全","link":"#容器-runtime-安全","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"云原生基础架构实战课/16｜云原生安全：不可忽视的关键因素.md","filePath":"云原生基础架构实战课/16｜云原生安全：不可忽视的关键因素.md","lastUpdated":1795537597000}'),r={name:"云原生基础架构实战课/16｜云原生安全：不可忽视的关键因素.md"};function n(p,e,o,s,u,h){return l(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="_16-云原生安全-不可忽视的关键因素" tabindex="-1">16 | 云原生安全：不可忽视的关键因素 <a class="header-anchor" href="#_16-云原生安全-不可忽视的关键因素" aria-label="Permalink to &quot;16 | 云原生安全：不可忽视的关键因素&quot;">​</a></h1><p>你好，我是潘野。</p><p>从今天开始我们进入安全章节，很多同学可能有点疑惑，我们不是讲基础架构自动化的吗？这与安全有多少关联呢？</p><p>其实关联还是挺高的，因为在云原生体系中，安全就像盖房子时的地基，如果地基不牢固，房子就很容易倒塌。所以，我们需要格外地重视安全。学完今天的内容，相信你会对云原生的安全体系建立更深刻的认识。</p><h2 id="云原生安全的特点" tabindex="-1">云原生安全的特点 <a class="header-anchor" href="#云原生安全的特点" aria-label="Permalink to &quot;云原生安全的特点&quot;">​</a></h2><p>我们先来分析一下云原生的安全问题有什么特点。</p><p>首先，云原生应用的攻击面更大。传统的应用通常位于一个数据中心内，以往我们做好单数据中心的安全措施基本可以抵挡住 90% 的攻击。而云原生应用可能分布在多个数据中心甚至多个云上，那么攻击者自然更容易找到攻击目标，所以这就提升了我们防护的难度。</p><p>其次，云原生应用的组件通常是动态创建和销毁的，这使得传统的、基于静态配置的安全防护措施难以跟上。</p><p>然后，云原生应用通常使用容器和微服务等技术。这些技术虽然带来了很多好处，但也带来了新的安全挑战。传统的应用通常是一个整体，攻击者需要找到应用的入口才能进行攻击。而云原生应用，攻击者甚至可能从容器的漏洞发起攻击。</p><h2 id="云原生安全的-4-个-c" tabindex="-1">云原生安全的 4 个 C <a class="header-anchor" href="#云原生安全的-4-个-c" aria-label="Permalink to &quot;云原生安全的 4 个 C&quot;">​</a></h2><p>下面我们来看看云原生安全防护的思路。</p><p>Kubernetes 官方文档里曾经提出 4 个 C 安全防护的思路，分别是 Cloud、Cluster、Container和 Code。下图来自 Kubernetes 官方文档，图里很好地解释了这四个 C 的层级是由外到内、分层来解决安全问题的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E5%9F%BA%E7%A1%80%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/16/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E5%9F%BA%E7%A1%80%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/16/1.png" alt=""></a></p><p>而在最新的 Kubernetes官方文档中，从应用开发的角度重新定义了云原生安全的层级，改变了从外到内层层包裹的体系，更加关注整个应用生命周期中的安全问题。</p><p>从应用生命周期的角度来看，一共分成了四个阶段，分别是开发阶段、部署阶段、分发阶段，运行时的生命周期。这四个阶段各有各的关注点，我不同阶段对应的关注点做成了思维导图，供你参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E5%9F%BA%E7%A1%80%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/16/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E5%9F%BA%E7%A1%80%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/16/2.png" alt=""></a></p><p>无论是过去的 4C 安全体系，还是现在的应用四阶段的安全体系。在基础架构中，我们着重关注的是 Cloud、Cluster 和 Container 三个部分，对应到四个阶段中，主要是分发阶段、部署阶段、和运行时的生命周期三个阶段。不过需要注意的是，它们之间不是一一对应，而是一种复杂的重合关系。</p><p>接下来，我会基于 4C 体系将这些内容拆开来，逐一为你详细讲解，同时将分发阶段、部署阶段，还有运行时生命周期三个阶段与之一一对应</p><h2 id="cloud" tabindex="-1">Cloud <a class="header-anchor" href="#cloud" aria-label="Permalink to &quot;Cloud&quot;">​</a></h2><p>云安全由云提供商和用户共同承担的，这里的用户不仅仅是公司或者团队，还包括部署在云上的应用。那么云提供商自然就要负责提供基础设施安全和平台安全，这其中包括物理安全、网络安全、数据安全和应用程序安全等。而用户负责应用安全和数据安全，包括身份验证和授权、数据加密、访问控制、安全监控等。</p><p>一般来说，你可以在云提供商的产品页面里找到关于安全产品的介绍与文档，我们以 AWS 为例子，AWS 的安全文档中涵盖四个主题，安全基础知识、安全服务、安全最佳实践和安全案例。</p><p>这些主题能够帮助我们了解 AWS 安全架构、安全服务和安全最佳实践，但是内容非常多，我们如何抓住其中的重点呢？</p><p>结合我的经验来看，建议你着重了解以下几个方面，并且要能做到熟练使用。</p><ul><li><p>身份和访问管理（IAM）：了解如何使用 IAM 控制对 AWS 资源的访问。</p></li><li><p>加密：了解 AWS 提供的各种加密服务，例如 Amazon S3 加密、Amazon EBS 加密和AWS KMS。</p></li><li><p>网络安全：了解 AWS 提供的网络安全服务，例如 Amazon VPC、AWS Firewall Manager和 AWS WAF。</p></li><li><p>数据安全：了解 AWS 提供的数据安全服务，例如 Amazon CloudTrail、AWS CloudWatch和 AWS Config。</p></li><li><p>合规性：了解 AWS 如何帮助您满足各种合规性要求，例如 GDPR 和 PCI DSS。</p></li></ul><p>对于其他的云提供商，其实主体思路也大致相同，重点要关注各个云厂商在身份管理、加密、网络安全、数据安全以及合规性等方面的文档。</p><p>那有同学一定会问了，公司是自建机房或者自建的私有云，没有公有云安全那么全的功能，又该如何应对呢？</p><p>其实在私有云或者自建机房中依然是针对身份管理、加密、网络安全、数据安全还有合规性这五个方面来实施，有很多商业或者开源安全软件可以帮你解决这五个方向的安全问题。</p><h2 id="cluster" tabindex="-1">Cluster <a class="header-anchor" href="#cluster" aria-label="Permalink to &quot;Cluster&quot;">​</a></h2><p>谈到集群安全，Kubernetes 在设计之初就仔细考虑过安全问题。Kubernetes 的安全分成控制平面安全与数据平面的安全，那么集群安全几乎等同于前面提到的运行时生命周期。</p><h3 id="控制平面安全" tabindex="-1">控制平面安全 <a class="header-anchor" href="#控制平面安全" aria-label="Permalink to &quot;控制平面安全&quot;">​</a></h3><p>那么在 Kubernetes 控制平面的安全主要是由 apiserver 来完成的。简单来说，当对集群发起一个操作请求，在 apiserver 的内部有三个步骤，分别是认证、鉴权和准入机制。apiserver 会先验证请求者的合法性，接下来判断对请求的资源是否有操作权限，最后准入机制会根据情况修改或拒绝请求。</p><p>从 Kubernetes 1.21 开始，Kubernetes 加强了控制平面的安全功能，推荐使用 OPA（OpenPolicy Agent）与 Kubernetes API 服务器集成，可以对所有的 kubernetes 资源在创建、更新或删除 Kubernetes 资源之前进行授权和准入控制。</p><h3 id="数据平面安全" tabindex="-1">数据平面安全 <a class="header-anchor" href="#数据平面安全" aria-label="Permalink to &quot;数据平面安全&quot;">​</a></h3><p>数据平面的安全主要集中在两个关键方面：网络隔离和数据加密。</p><p>Kubernetes 提供了 NetworkPolicy 和 Service Mesh 两种机制来加强网络隔离。</p><ul><li><p>NetworkPolicy 可以控制 Pod 之间的网络访问，以限制攻击面。</p></li><li><p>Service Mesh，例如 Istio，通过提供 MTLS（双向 TLS）功能，为 Pod 间的通信实现加密和身份验证，从而进一步增强安全性。Kubernetes 提供了多种数据加密措施，以保护敏感数据安全。这些措施包括 Secrets 加密、使用 CSI 驱动程序加密存储卷，以及使用 Vault 等工具管理密钥。这个我们在后面的章节再详细讲解。</p></li></ul><p>在网络层面，云原生体系采用 TLS 加密技术贯穿整个交互过程，确保网络流量的安全。其中TLS 证书的管理是非常重要的一环。</p><p>Kubernetes 使用多种类型的证书，主要是两类证书，一类是服务端 / 客户端证书，用于验证服务端客户端身份；一类是 CA 证书，用于签发证书。</p><p>我们可以将 Kubernetes 集群看成一个公司，证书就像员工的工牌。工牌可以证明员工的身份，并允许他们进入公司。CA 证书就是公司的安保部门负责颁发工牌。安保部门需要确保工牌是真实有效的，并且不会被滥用。</p><h2 id="容器-runtime-安全" tabindex="-1">容器 runtime 安全 <a class="header-anchor" href="#容器-runtime-安全" aria-label="Permalink to &quot;容器 runtime 安全&quot;">​</a></h2><p>容器 runtime 安全是指在容器运行期间对其进行保护，防止各种潜在的安全威胁。运行时安全对于容器来说至关重要，因为在这个阶段，容器面临着诸多安全风险，如代码注入、资源滥用、逃逸攻击等。一旦攻击者在容器运行时获得控制权，他们可以轻易地操纵应用，造成数据泄露、服务中断等严重后果。</p><p>容器运行时安全，常见的错误做法包括后面这四类。</p><ul><li><p>使用不安全的镜像：镜像是容器的基础，如果镜像本身存在安全漏洞或恶意代码，那么容器运行时也会受到威胁。因此，在使用镜像之前，应仔细检查其安全性，确保其来自可靠的来源。</p></li><li><p>以 root 用户运行容器：容器默认情况下是以 root 用户运行的，这会导致容器拥有过大的权限，从而增加攻击者利用漏洞获取控制权的风险。因此，应尽量避免以 root 用户运行容器，并为容器设置最小特权。</p></li><li><p>未启用安全功能：大多数容器 runtime 都提供了丰富的安全功能。这些功能可以有效地限制容器的行为，降低安全风险。因此，我们应尽可能启用这些安全功能。</p></li><li><p>忽略运行时安全监控：容器 runtime 安全监控可以帮助我们及时发现容器中的异常行为，并采取措施阻止攻击。因此，我们应建立完善的运行时安全监控机制，并定期进行安全检查。</p></li></ul><p>根据上面这些错误的做法，我们不难得出一些容器 runtime 安全最佳实践。</p><p>首先是使用安全可靠的镜像。容器文件系统应只包含必要的应用程序文件和数据，我们可以将镜像的管理贯穿在应用的分发阶段，通过 DevOps 的 CI 流水线对镜像做到自动化扫描，将不可靠的镜像排除在环境之外。</p><p>其次，容器应以最小特权原则运行，即以非 root 用户身份执行，并仅配备完成其任务所需的最低权限。</p><p>最后，Seccomp、Cgroups、SELinux 等容器运行时安全功能可以增强安全性。具体来说，Seccomp 限制容器可执行的系统调用以防止代码执行漏洞；Cgroups 控制资源使用，如CPU、内存和磁盘，以避免资源滥用；而 SELinux 则强制容器在特定安全策略下运行，进一步增强安全护。</p><p>通过遵循这些最佳实践，可以有效地提升容器 runtime 安全性，降低安全风险。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天，我们探讨了 Kubernetes 官方对云原生安全体系的定义。这一定义现在已经从基于基础设施的 4C 层级模型，转变为以应用为核心。这表明安全策略需要覆盖应用的整个生命周期，从开发、部署到运行。</p><p>尽管这种定义上的转变，技术层面的变化并不显著，但这种趋势仍然值得我们多加关注。</p><p>在开发阶段，包括代码审查、模糊测试和零信任架构（ZTA）等安全措施，已被多数云服务提供商纳入其产品中，这对应于 4C 模型中的 “Cloud” 和 “Code”。</p><p>而分发阶段、部署阶段、运行时的生命周期这三个阶段中的安全措施，贯穿在 4C 中 Cluster和 container 的管理中。例如容器镜像的安全、容器权限的控制、集群权限管理、应用数据加密，网络隔离这些手段，都是在 Cluster 和 container 级别完成的。</p><p>在接下来的章节中，我们会重点介绍我们该如何将云原生安全措施落地，确保它们有效地提供安全保护，真正发挥防火作用。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>在 Kubernetes 集群和容器级别，具体有哪些安全软件来完成安全防护？</p><p>欢迎在评论区与我讨论。如果这一讲对你有启发，也欢迎分享给身边更多朋友。</p>',57)])])}const d=t(r,[["render",n]]);export{E as __pageData,d as default};
